StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Fôring                                                                                                                                                                                                                                                                            
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE					SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0				2023-06-16			William Veim			Initial release                                                                                                                                                                                                                                  
// 1.2.0				2023-08-02 			Daniel Årvik				Lagt inn innlesing av fôrtabell og fôrsøyler
// 1.2.1				2024-03-18			Sondre Asheim		Oversatt kode til engelsk
// 1.3.0				2024-04-21			William Veim			Official release v1
// 1.3.1				2024-04-25			William Veim			Lagt til feil og status i struktur
// 1.3.2				2024-04-27			William Veim			Bugfix status og feil
// 1.3.3				2024-04-27			William Veim			Bugfix økning av snittvekt ved midnatt
// 1.3.4				2024-04-27			William Veim			Bugfix SGR verdi kalkulasjon
// 1.3.5				2024-05-02			William Veim			Bugfix fôrmengde idag ved aut mode
// 1.3.6				2024-05-08			William Veim			Bugfix calulation TGC and SGR
// 1.4.0				2024-07-27			William Veim			Rework select ref temperature - Select analog index
// 1.4.1				2026-04-24			William Veim			Bugfix calculating feed amount tomorrow
// 2.0.0				2026-05-14			William Veim			Major rework (scaling table values, feed plan, added screw offset and rework calculations))
//
//===============================================================================================================================

(*************************************************************************
 *	VARIABLE CONTROL
 *************************************************************************)

Current_Time := TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);
DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct);
Current_Date := DT_TO_DATE(GetTime());
Current_TimeStamp :=CONCAT(In1:=CONCAT(In1:=DateToString(Current_Date), In2:=' '), In2:=DELETE(In:=TODToString(Current_TIME), L:=13, P:=6));
RE_MidnightPulse(Clk:=Current_Time=TIME_OF_DAY#00:00:00);

(*************************************************************************
 *	INITIALISING VARIABELS
 *************************************************************************)

Ext_FeedControl.EXT_General.LocationIndex[0]:=					Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_FeedControl.EXT_Alarm.Sts_SupressIfOff_Visible:=			TRUE;
Ext_FeedControl.EXT_General.Controlled_FromController:=	Cfg_ControllerName;
Ext_FeedControl.EXT_General.FeedScrew2_InUse:= 				Cfg_FeedScrew2_InUse;
Ext_FeedControl.EXT_General.FeedScrew_Type:=					Cfg_FeedScrewType;

IF NOT Ext_FeedControl.INT_Data.Initialise THEN
	
	//Operator settings
	Ext_FeedControl.EXT_Operator.Amount_Deadfish_TS:=DateToString(Current_Date);
	Ext_FeedControl.EXT_Operator.Appetite_Factor_TS:=DateToString(Current_Date);
	Ext_FeedControl.EXT_Operator.Appetite_Factor:=100;
	Ext_FeedControl.EXT_Operator.Temperature_Select:=0;
	Ext_FeedControl.EXT_Operator.SGR_Factor_Select:=0;
	Ext_FeedControl.EXT_Operator.SGR_Factor_Manual:=1;
	Ext_FeedControl.EXT_Operator.FCR_Factor_Select:=0;
	Ext_FeedControl.EXT_Operator.FCR_Factor_Manual:=1;
	Ext_FeedControl.EXT_Operator.ControlMode:=0;
	Ext_FeedControl.EXT_Operator.Pulse_Time:=4;
	Ext_FeedControl.EXT_Operator.Temperature_Manual:=10;
	
	//Engeneering settings
	Ext_FeedControl.EXT_Engineering.FeedControl_Option:=1;
	
	//State config
	Ext_FeedControl.EXT_Engineering.StateCfg_1.Cfg_Quality:=0; //Puls/pause time fault = Diagnostic
	Ext_FeedControl.EXT_Engineering.StateCfg_1.Cfg_Alarm:=TRUE; //Puls/pause time fault = Alarm
	Ext_FeedControl.EXT_Engineering.StateCfg_2.Cfg_Quality:=0; //Feed factor out of bounds = Diagnostic
	Ext_FeedControl.EXT_Engineering.StateCfg_2.Cfg_Alarm:=TRUE; //Feed factor out of bounds = Alarm
	Ext_FeedControl.EXT_Engineering.StateCfg_3.Cfg_Quality:=0; //SGR factor out of bounds = Diagnostic
	Ext_FeedControl.EXT_Engineering.StateCfg_3.Cfg_Alarm:=TRUE; //SGR factor out of bounds = Alarm
	Ext_FeedControl.EXT_Engineering.StateCfg_4.Cfg_Quality:=0; //Apetite factor out of bounds = Diagnostic
	Ext_FeedControl.EXT_Engineering.StateCfg_4.Cfg_Alarm:=TRUE; //Apetite factor out of bounds = Alarm
	Ext_FeedControl.EXT_Engineering.StateCfg_5.Cfg_Quality:=0; //Interlock = Diagnostic
	Ext_FeedControl.EXT_Engineering.StateCfg_5.Cfg_Alarm:=TRUE; //Interlock = Alarm
	Ext_FeedControl.EXT_Engineering.StateCfg_6.Cfg_Quality:=0; //Feed amount impossible = Diagnostic
	Ext_FeedControl.EXT_Engineering.StateCfg_6.Cfg_Alarm:=TRUE; //Feed amount impossible = Alarm
	
	//Other
	Wrk_ResetGroup:= Current_Date;
	
	//Alarm settings
	Ext_FeedControl.EXT_Alarm.Cfg_SupressDelayOff:=10;
	Ext_FeedControl.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	Ext_FeedControl.EXT_Alarm.Cfg_AlarmReturnDelay:=10;
	
	//Init complete
	Ext_FeedControl.INT_Data.Initialise :=TRUE;
	
END_IF;

(*******************************************************************************
 *	EXECUTING FUNCTION FOR DATA RETRIVING
 * 	NB! Only one fb is allowed to retrive data each cycle (reduce cycle time)
 *******************************************************************************)

IF Ext_FeedControl.INT_Data.CurrentIndex = Ext_FeedControl_Common.INT_Data.RetriveIndex THEN
	
	HE_FeedControl_RetriveData(Ext_FeedControl:=Ext_FeedControl, 
													Ext_FeedControl_Common:=Ext_FeedControl_Common, 
													Ext_AnalogValue:=Ext_AnalogValue, 
													Temperature_Current=>Ext_FeedControl.EXT_Operator.Temperature_Current, 
													SGR_Factor=>Ext_FeedControl.EXT_Operator.SGR_Factor_Current, 
													FCR_Factor=>Ext_FeedControl.EXT_Operator.FCR_Factor_Current, 
													FeedScrew1_AmountPerSec=>Wrk_FeedScrew1_CurrentAmount, 
													FeedScrew2_AmountPerSec=>Wrk_FeedScrew2_CurrentAmount);
	
END_IF;

(*************************************************************************
 *	CALIBRATION SEQUENCE
 *************************************************************************)
 
 // Puls time during calibration (Normaly using calculated pulse time, else 3sec)
 IF Ext_FeedControl.EXT_Operator.Pulse_Time > 1 THEN
	 TON_CalibrationStart_Pulse.PT:=NanoSecToTime(REAL_TO_LINT(Ext_FeedControl.EXT_Operator.Pulse_Time*1000000000.0));
 ELSE
 	TON_CalibrationStart_Pulse.PT:=TIME#3s;
 END_IF;
 
// Timers start delay, pulse and pause time
TON_CalibrationStartDelay(In:=Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_LowSpeed OR Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_HighSpeed OR Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_LowSpeed OR Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_HighSpeed, PT:=TIME#20s);
TON_CalibrationStart_Pause(In:=TON_CalibrationStartDelay.Q AND Wrk_CalibrationAlternate AND NOT TON_CalibrationStop_Delay.In, PT:=TIME#2s );
TON_CalibrationStart_Pulse(In:=CalibrationPulse_Time <= TIME#20s AND TON_CalibrationStartDelay.Q AND NOT Wrk_CalibrationAlternate AND NOT TON_CalibrationStop_Delay.In);
TON_CalibrationStop_Delay(In:=CalibrationPulse_Time >= TIME#20s, PT:=TIME#20s);

//Alternating puls and pause timer
IF TON_CalibrationStart_Pause.Q THEN
	Wrk_CalibrationAlternate:=FALSE;
ELSIF TON_CalibrationStart_Pulse.Q THEN
	Wrk_CalibrationAlternate:=TRUE;
END_IF;

//Accumulating total pulse time (calibration completed when total equal 20s)
IF TON_CalibrationStart_Pulse.In THEN
	
	CalibrationPulse_Time:=ADD_TIME(In1:=CalibrationPulse_Time, In2:=GetMyTaskInterval());
END_IF;

//20sec stop delay after calibration completed
IF TON_CalibrationStop_Delay.Q THEN
	
	Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_LowSpeed:=FALSE;
	Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_HighSpeed:=FALSE;
	Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_LowSpeed:=FALSE;
	Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_HighSpeed:=FALSE;
	CalibrationPulse_Time:=TIME#0s;
END_IF;

//Screw output
Wrk_Calibration_StartScrew1:= (Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_LowSpeed OR Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_HighSpeed) AND TON_CalibrationStart_Pulse.In AND NOT TON_CalibrationStart_Pulse.Q AND NOT TON_CalibrationStop_Delay.In;
Wrk_Calibration_StartScrew2:= (Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_LowSpeed OR Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_HighSpeed) AND TON_CalibrationStart_Pulse.In AND NOT TON_CalibrationStart_Pulse.Q AND NOT TON_CalibrationStop_Delay.In;

IF Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_LowSpeed THEN
	Wrk_Speed_FeedScrew1:=25;
ELSIF Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_HighSpeed THEN
	Wrk_Speed_FeedScrew1:=75;
END_IF;
	
IF Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_LowSpeed THEN
	Wrk_Speed_FeedScrew2:=25;
ELSIF Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_HighSpeed THEN
	Wrk_Speed_FeedScrew2:=75;
END_IF;

(*************************************************************************
 *	CALCULATIONS
 *************************************************************************)

//Calculate total amount per sec
IF Cfg_FeedScrew2_InUse THEN
	CASE Ext_FeedControl.EXT_Engineering.FeedControl_Option OF
		
		0: //Mengde per sek basert på tilgjengelighet skrue
			IF Inp_FeedScrew1_Available AND (Inp_FeedScrew2_Available AND Cfg_FeedScrew2_InUse) THEN
				Ext_FeedControl.EXT_Operator.Total_AmountPrSec := Wrk_FeedScrew1_CurrentAmount + Wrk_FeedScrew2_CurrentAmount;
			ELSIF Inp_FeedScrew1_Available AND (NOT Inp_FeedScrew2_Available AND Cfg_FeedScrew2_InUse) THEN
				Ext_FeedControl.EXT_Operator.Total_AmountPrSec := Wrk_FeedScrew1_CurrentAmount;
			ELSIF NOT Inp_FeedScrew1_Available AND  (Inp_FeedScrew2_Available AND Cfg_FeedScrew2_InUse) THEN
				Ext_FeedControl.EXT_Operator.Total_AmountPrSec := Wrk_FeedScrew2_CurrentAmount;
			ELSE 
				Ext_FeedControl.EXT_Operator.Total_AmountPrSec :=0;
			END_IF;
		
		1: //Fast mengde lik total av skruer
			Ext_FeedControl.EXT_Operator.Total_AmountPrSec := Wrk_FeedScrew1_CurrentAmount + Wrk_FeedScrew2_CurrentAmount;
		
	END_CASE;
ELSE //Only one feed screw in use
	Ext_FeedControl.EXT_Operator.Total_AmountPrSec := Wrk_FeedScrew1_CurrentAmount;
END_IF;

//Calculating biomass
Ext_FeedControl.EXT_Operator.Biomass_Current := 		(( Ext_FeedControl.EXT_Operator.Weight_AVG / 1000 ) *  Ext_FeedControl.EXT_Operator.Amount_Fish ) / 1000;
Ext_FeedControl.EXT_Operator.Biomass_Tomorrow := 	Ext_FeedControl.EXT_Operator.Biomass_Current + (( Ext_FeedControl.EXT_Operator.Feed_Amount_Today / Ext_FeedControl.EXT_Operator.FCR_Factor_Current ) / 1000);

//Calculating avg weight (each 10min)
Wrk_AvgWeight_TimeSinceLastSample:=ADD_TIME(In1:=Wrk_AvgWeight_TimeSinceLastSample, In2:=GetMyTaskInterval());

//Ensurance to not fuck up average weigt data
IF Wrk_AvgWeight_TimeSinceLastSample > TIME#10m 
	AND ( Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total - Wrk_AvgWeight_FeedLastCalc ) > 1
	AND Ext_FeedControl.EXT_Operator.FCR_Factor_Current > 0 
	AND Ext_FeedControl.EXT_Operator.Amount_Fish > 0 THEN
	
	Ext_FeedControl.EXT_Operator.Weight_AVG:= 	(((Ext_FeedControl.EXT_Operator.Biomass_Current * 1000) + ((Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total-Wrk_AvgWeight_FeedLastCalc) / Ext_FeedControl.EXT_Operator.FCR_Factor_Current ))  / Ext_FeedControl.EXT_Operator.Amount_Fish)  * 1000;
	Wrk_AvgWeight_TimeSinceLastSample:=			TIME#0s;
	Wrk_AvgWeight_FeedLastCalc:=							Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total;
	
END_IF;

//Calculate feed amount delivered today
Ext_FeedControl.EXT_Operator.Feed_Amount_Current_FeedScrew1:=(ULINT_TO_REAL(TimeToSec(Wrk_TotalTime_Today_FeedScrew1))*Wrk_FeedScrew1_CurrentAmount)/1000;
Ext_FeedControl.EXT_Operator.Feed_Amount_Current_FeedScrew2:=(ULINT_TO_REAL(TimeToSec(Wrk_TotalTime_Today_FeedScrew2))*Wrk_FeedScrew2_CurrentAmount)/1000;
Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total:=Ext_FeedControl.EXT_Operator.Feed_Amount_Current_FeedScrew1 + Ext_FeedControl.EXT_Operator.Feed_Amount_Current_FeedScrew2;

//Calculate amout per feed pulse
Ext_FeedControl.EXT_Operator.FeedPulse_Amount:= Ext_FeedControl.EXT_Operator.Pulse_Time * Ext_FeedControl.EXT_Operator.Total_AmountPrSec;

(*************************************************************************
 *	FEED CONTROL
 *************************************************************************)
 
//CALCULATE FEED AMOUNT
CASE Ext_FeedControl.EXT_Operator.Mode OF
	
	//OFF
    0:
		//Today
		Ext_FeedControl.EXT_Operator.Feed_Amount_Today := 0;
		
		//Tomorrow
		Ext_FeedControl.EXT_Operator.Feed_Amount_Tomorrow:=0;
		
	//MANUAL
	1:
		//Today
		Ext_FeedControl.EXT_Operator.Feed_Amount_Today := Ext_FeedControl.EXT_Operator.Feed_Amount_Manual;
		
		//Tomorrow
		IF Ext_FeedControl.EXT_Operator.Feed_Amount_Manual_DailyIncrease > 0 THEN //Increase value above zero
			Ext_FeedControl.EXT_Operator.Feed_Amount_Tomorrow := Ext_FeedControl.EXT_Operator.Feed_Amount_Today * ((Ext_FeedControl.EXT_Operator.Feed_Amount_Manual_DailyIncrease / 100) + 1);
		ELSE //Increase value not used
			Ext_FeedControl.EXT_Operator.Feed_Amount_Tomorrow := Ext_FeedControl.EXT_Operator.Feed_Amount_Today;
		END_IF;
		
	//AUTO
	2:
		//Today
		Ext_FeedControl.EXT_Operator.Feed_Amount_Today := (((Ext_FeedControl.EXT_Operator.Biomass_Current * 1000) * Ext_FeedControl.EXT_Operator.SGR_Factor_Current * Ext_FeedControl.EXT_Operator.FCR_Factor_Current) / 100) * (Ext_FeedControl.EXT_Operator.Appetite_Factor / 100 );
			
		//Tomorrow
		Ext_FeedControl.EXT_Operator.Feed_Amount_Tomorrow := (((Ext_FeedControl.EXT_Operator.Biomass_Tomorrow * 1000) * Ext_FeedControl.EXT_Operator.SGR_Factor_Current * Ext_FeedControl.EXT_Operator.FCR_Factor_Current) / 100) * (Ext_FeedControl.EXT_Operator.Appetite_Factor / 100 );
END_CASE;

//CALCULATE PULS/PAUSE TIME (Based on feed plan etc)
CASE Ext_FeedControl.EXT_Operator.ControlMode OF 
	
		//CONSTANT PULS TIME
		0:
			CASE Ext_FeedControl.EXT_Operator.FeedPlan_Select OF
				
				0: //Feed plan 1
					Ext_FeedControl.EXT_Operator.Pause_Time := ( 60 * (( Ext_FeedControl.EXT_Operator.Total_AmountPrSec / 1000 ) * Ext_FeedControl.EXT_Operator.Pulse_Time ) / ( Ext_FeedControl.EXT_Operator.Feed_Amount_Today * Ext_FeedControl_Common.INT_Data.FeedPlan1_Intensity )) - Ext_FeedControl.EXT_Operator.Pulse_Time;
					
				1: //Feed plan 2
					Ext_FeedControl.EXT_Operator.Pause_Time := ( 60 * (( Ext_FeedControl.EXT_Operator.Total_AmountPrSec / 1000 ) * Ext_FeedControl.EXT_Operator.Pulse_Time ) / ( Ext_FeedControl.EXT_Operator.Feed_Amount_Today * Ext_FeedControl_Common.INT_Data.FeedPlan2_Intensity )) - Ext_FeedControl.EXT_Operator.Pulse_Time;
					
				2: //Feed plan 3
					Ext_FeedControl.EXT_Operator.Pause_Time := ( 60 * (( Ext_FeedControl.EXT_Operator.Total_AmountPrSec / 1000 ) * Ext_FeedControl.EXT_Operator.Pulse_Time ) / ( Ext_FeedControl.EXT_Operator.Feed_Amount_Today * Ext_FeedControl_Common.INT_Data.FeedPlan3_Intensity )) - Ext_FeedControl.EXT_Operator.Pulse_Time;
					
			END_CASE;
		
		//CONSTANT PAUSE TIME
		1:
			CASE Ext_FeedControl.EXT_Operator.FeedPlan_Select OF
				
				0: //Feed plan 1
					Ext_FeedControl.EXT_Operator.Pulse_Time := ((Ext_FeedControl.EXT_Operator.Feed_Amount_Today * Ext_FeedControl_Common.INT_Data.FeedPlan1_Intensity) * Ext_FeedControl.EXT_Operator.Pause_Time ) / ((( Ext_FeedControl.EXT_Operator.Total_AmountPrSec / 1000) * 60 ) - ( Ext_FeedControl.EXT_Operator.Feed_Amount_Today * Ext_FeedControl_Common.INT_Data.FeedPlan1_Intensity ));
					
				1: //Feed plan 2
					Ext_FeedControl.EXT_Operator.Pulse_Time := ((Ext_FeedControl.EXT_Operator.Feed_Amount_Today * Ext_FeedControl_Common.INT_Data.FeedPlan2_Intensity) * Ext_FeedControl.EXT_Operator.Pause_Time ) / ((( Ext_FeedControl.EXT_Operator.Total_AmountPrSec / 1000) * 60 ) - ( Ext_FeedControl.EXT_Operator.Feed_Amount_Today * Ext_FeedControl_Common.INT_Data.FeedPlan2_Intensity ));
					
				2: //Feed plan 3
					Ext_FeedControl.EXT_Operator.Pulse_Time := ((Ext_FeedControl.EXT_Operator.Feed_Amount_Today * Ext_FeedControl_Common.INT_Data.FeedPlan3_Intensity) * Ext_FeedControl.EXT_Operator.Pause_Time ) / ((( Ext_FeedControl.EXT_Operator.Total_AmountPrSec / 1000) * 60 ) - ( Ext_FeedControl.EXT_Operator.Feed_Amount_Today * Ext_FeedControl_Common.INT_Data.FeedPlan3_Intensity ));
					
			END_CASE;
			
END_CASE;

IF Ext_FeedControl.EXT_Operator.Pause_Time<0 THEN
	Ext_FeedControl.EXT_Operator.Pause_Time:=0;
END_IF;

IF Ext_FeedControl.EXT_Operator.Pulse_Time<0 THEN
	Ext_FeedControl.EXT_Operator.Pulse_Time:=0;
END_IF;

// Timers for feed output
IF Ext_FeedControl.EXT_Operator.Mode > 0 AND Ext_FeedControl.EXT_Operator.Pause_Time > 0 AND Ext_FeedControl.EXT_Operator.Pulse_Time > 0 THEN
	IF TON_PauseTime.Q THEN
		Timer_Alternate:=FALSE;
	ELSIF TON_PulseTime.Q THEN
		Timer_Alternate:=TRUE;
	END_IF;
	TON_PauseTime(In:=Timer_Alternate, PT:=NanoSecToTime(REAL_TO_LINT(Ext_FeedControl.EXT_Operator.Pause_Time*1000000000.0)));
	TON_PulseTime(In:= NOT Timer_Alternate, PT:=NanoSecToTime(REAL_TO_LINT(Ext_FeedControl.EXT_Operator.Pulse_Time*1000000000.0)));
ELSE
	TON_PauseTime(In:=FALSE, PT:=TIME#0s);
	TON_PulseTime(In:=FALSE, PT:=TIME#0s);
END_IF;

//CONTROL OF OUTPUT
IF ((Ext_FeedControl_Common.INT_Data.FeedPlan1_Intensity > 0 AND Ext_FeedControl.EXT_Operator.FeedPlan_Select = 0)
	OR (Ext_FeedControl_Common.INT_Data.FeedPlan2_Intensity > 0 AND Ext_FeedControl.EXT_Operator.FeedPlan_Select = 1)
	OR (Ext_FeedControl_Common.INT_Data.FeedPlan3_Intensity > 0 AND Ext_FeedControl.EXT_Operator.FeedPlan_Select = 2))
	AND Ext_FeedControl.EXT_Operator.Pause_Time >0 AND Ext_FeedControl.EXT_Operator.Pulse_Time >0 AND NOT Inp_Interlock THEN
	
	Wrk_Speed_FeedScrew1:=Ext_FeedControl.EXT_Operator.FeedScrew1_Speed;
	
	//Control feed screw 1
	IF Inp_FeedScrew1_Available AND NOT (Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_LowSpeed OR Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_HighSpeed) THEN
		
		Wrk_OutputFeedScrew1 := TON_PulseTime.In AND NOT TON_PulseTime.Q;
		
	ELSE
		
		Wrk_OutputFeedScrew1 :=FALSE;
		
	END_IF;
	
	//Control of feed screw 2
	//Option to have offset from feed scew 1
	IF Cfg_FeedScrew2_InUse AND Inp_FeedScrew2_Available AND NOT (Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_LowSpeed OR Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_HighSpeed) THEN
		
		Wrk_Speed_FeedScrew2:=Ext_FeedControl.EXT_Operator.FeedScrew2_Speed;
		
		CASE Ext_FeedControl.EXT_Engineering.FeedScrew_Offset OF
		
		0: //Syncrone output
		
			Wrk_OutputFeedScrew2:= TON_PulseTime.In AND NOT TON_PulseTime.Q;
			
		1: //25% offset

			TON_PulseTime_Screw2(In:=LINT_TO_REAL(TimeToSec(TON_PauseTime.ET)) > (LINT_TO_REAL(TimeToSec(TON_PauseTime.PT)) * 0.25), PT:=NanoSecToTime(REAL_TO_LINT(Ext_FeedControl.EXT_Operator.Pulse_Time*1000000000.0)));
			Wrk_OutputFeedScrew2:=TON_PulseTime_Screw2.In AND NOT TON_PulseTime_Screw2.Q;
	
		2: //50% offset
	
			TON_PulseTime_Screw2(In:=LINT_TO_REAL(TimeToSec(TON_PauseTime.ET)) > (LINT_TO_REAL(TimeToSec(TON_PauseTime.PT)) * 0.5), PT:=NanoSecToTime(REAL_TO_LINT(Ext_FeedControl.EXT_Operator.Pulse_Time*1000000000.0)));
			Wrk_OutputFeedScrew2:=TON_PulseTime_Screw2.In AND NOT TON_PulseTime_Screw2.Q;
	
		END_CASE;
		
	ELSE
		
		Wrk_OutputFeedScrew2:=FALSE;
		
	END_IF;
	
ELSE
	
	Wrk_OutputFeedScrew1:=FALSE;
	Wrk_OutputFeedScrew2 :=FALSE;
	
END_IF;

(*************************************************************************
 *	STATISTIC
 *************************************************************************)
 
//Feed screw 1 
FB_FeedScrew1_Stat(Inp_Feedback:=Inp_FeedScrew1_Feedback, 
									Inp_Reset_Total:=Ext_FeedControl.EXT_Statistics.FeedScrew1_TotalRunTime_Reset,
									Inp_Reset_Service:=Wrk_Dummy);

Ext_FeedControl.EXT_Statistics.FeedScrew1_TotalNumberOfStart:= 	ULINT_TO_UINT(FB_FeedScrew1_Stat.Out_NumOfStarts);
Ext_FeedControl.EXT_Statistics.FeedScrew1_TotalRunTime:=				TimeToSec(FB_FeedScrew1_Stat.Out_RunTime_Total);
Ext_FeedControl.EXT_Statistics.FeedScrew1_TotalRunTime_TS:=		FB_FeedScrew1_Stat.Out_ResetDate_Total;

//Feed screw 2 
FB_FeedScrew2_Stat(Inp_Feedback:=Inp_FeedScrew2_Feedback, 
									Inp_Reset_Total:=Ext_FeedControl.EXT_Statistics.FeedScrew2_TotalRunTime_Reset,
									Inp_Reset_Service:=Wrk_Dummy);

Ext_FeedControl.EXT_Statistics.FeedScrew2_TotalNumberOfStart:= 	ULINT_TO_UINT(FB_FeedScrew2_Stat.Out_NumOfStarts);
Ext_FeedControl.EXT_Statistics.FeedScrew2_TotalRunTime:=				TimeToSec(FB_FeedScrew2_Stat.Out_RunTime_Total);
Ext_FeedControl.EXT_Statistics.FeedScrew2_TotalRunTime_TS:=		FB_FeedScrew2_Stat.Out_ResetDate_Total;

//Accumulating runtime today (Used to calculate feed amount today)
IF Wrk_OutputFeedScrew1 AND NOT (Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_LowSpeed OR Ext_FeedControl.EXT_Engineering.FeedScrew1_CalibrationData.Calibration_HighSpeed) THEN
	Wrk_TotalTime_Today_FeedScrew1:=ADD_TIME(Wrk_TotalTime_Today_FeedScrew1, GetMyTaskInterval());
END_IF;

IF Wrk_OutputFeedScrew2 AND NOT (Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_LowSpeed OR Ext_FeedControl.EXT_Engineering.FeedScrew2_CalibrationData.Calibration_HighSpeed) THEN
	Wrk_TotalTime_Today_FeedScrew2:=ADD_TIME(Wrk_TotalTime_Today_FeedScrew2, GetMyTaskInterval());
END_IF;

//Resett data when feeding is done
IF RE_MidnightPulse.Q THEN
	Ext_FeedControl.EXT_Statistics.Group_Days:=								Ext_FeedControl.EXT_Statistics.Group_Days + 1;
	Ext_FeedControl.EXT_Statistics.Group_DegreeDays:=					Ext_FeedControl.EXT_Statistics.Group_DegreeDays + Ext_FeedControl.EXT_Operator.Temperature_Current;
	Ext_FeedControl.EXT_Statistics.Feed_Amount_Yesterday:=			Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total;
	Ext_FeedControl.EXT_Statistics.Group_TotalFeedAmount:=		Ext_FeedControl.EXT_Statistics.Group_TotalFeedAmount +Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total;
	Wrk_GroupTotalFeed:=																Ext_FeedControl.EXT_Statistics.Group_TotalFeedAmount;
	Ext_FeedControl.EXT_Statistics.Group_SGR_Calculated:=			((Ext_FeedControl.EXT_Operator.Weight_AVG - Wrk_AVGWeight_Start) / UINT_TO_REAL(Ext_FeedControl.EXT_Statistics.Group_Days)) * 100.0;
	Ext_FeedControl.EXT_Statistics.Group_TGC_Calculated:=			((Ext_FeedControl.EXT_Operator.Weight_AVG ** (1/3)) - (Wrk_AVGWeight_Start ** (1/3)) / Ext_FeedControl.EXT_Statistics.Group_DegreeDays);
	Ext_FeedControl.EXT_Statistics.Group_EFF_Calculated:=				(((Ext_FeedControl.EXT_Operator.Biomass_Current*1000) - (Wrk_Biomass_Start*1000)) / Ext_FeedControl.EXT_Statistics.Group_TotalFeedAmount);
	Ext_FeedControl.EXT_Statistics.Group_BFF_Calculated:=				(Ext_FeedControl.EXT_Statistics.Group_TotalFeedAmount / ((Ext_FeedControl.EXT_Operator.Biomass_Current*1000) - (Wrk_Biomass_Start*1000)) + (Ext_FeedControl.EXT_Statistics.Group_Amount_Deadfish));
	Ext_FeedControl.EXT_Operator.Amount_Deadfish_Today := 		0;
	Wrk_AvgWeight_FeedLastCalc:=													0;
	Wrk_TotalTime_Today_FeedScrew1:=TIME#0s;
	Wrk_TotalTime_Today_FeedScrew2:=TIME#0s;
	
	IF Ext_FeedControl.EXT_Operator.Mode = 1 AND Ext_FeedControl.EXT_Operator.Feed_Amount_Manual_DailyIncrease > 0 THEN
		Ext_FeedControl.EXT_Operator.Feed_Amount_Manual := Ext_FeedControl.EXT_Operator.Feed_Amount_Manual * ((Ext_FeedControl.EXT_Operator.Feed_Amount_Manual_DailyIncrease / 100) + 1);
	END_IF;
END_IF;

//Accumulating feed amount
Clear(Ext_FeedControl.EXT_Statistics.Feed_Amount_Week);
Clear(Ext_FeedControl.EXT_Statistics.Feed_Amount_Month);
Clear(Ext_FeedControl.EXT_Statistics.Feed_Amount_Year);
Clear(Ext_FeedControl.EXT_Statistics.Group_TotalFeedAmount);

Ext_FeedControl.EXT_Statistics.Feed_Amount_Week:=			Wrk_FeedAmountWeek + 	Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total;
Ext_FeedControl.EXT_Statistics.Feed_Amount_Month:=			Wrk_FeedAmountMonth +	Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total;
Ext_FeedControl.EXT_Statistics.Feed_Amount_Year:=				Wrk_FeedAmountYear + 	Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total;
Ext_FeedControl.EXT_Statistics.Group_TotalFeedAmount:= 	Wrk_GroupTotalFeed + 		Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total;

IF RE_MidnightPulse.Q THEN
	Wrk_FeedAmountWeek:= 	Wrk_FeedAmountWeek + 	Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total;
	Wrk_FeedAmountMonth:= 	Wrk_FeedAmountMonth + Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total;
	Wrk_FeedAmountYear:= 		Wrk_FeedAmountYear + 	Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total;
	Wrk_GroupTotalFeed:= 		Wrk_GroupTotalFeed + 		Ext_FeedControl.EXT_Operator.Feed_Amount_Current_Total;
END_IF;

//Checks if new week
IF GetWeekOfYear(DateStructToDt(DateStruct_Sample)) <> GetWeekOfYear(DateStructToDt(DateStruct)) THEN
	Clear(Wrk_FeedAmountWeek);
	Clear(Ext_FeedControl.EXT_Statistics.Feed_Amount_Week);
END_IF;

//Checks if new month
IF DateStruct_Sample.Month <> DateStruct.Month THEN
	Clear(Wrk_FeedAmountMonth);
	Clear(Ext_FeedControl.EXT_Statistics.Feed_Amount_Month);
END_IF;
			
//Checks if new year
IF DateStruct_Sample.Year <> DateStruct.Year THEN
	Clear(Wrk_FeedAmountYear);
	Clear(Ext_FeedControl.EXT_Statistics.Feed_Amount_Year);
END_IF;

// Sampling date
DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct_Sample);

//Adding deadfish
IF Ext_FeedControl.EXT_Operator.Add_DeadFish AND Ext_FeedControl.EXT_Operator.Amount_Deadfish > 0 THEN
	IF Ext_FeedControl.EXT_Operator.Amount_Fish > Ext_FeedControl.EXT_Operator.Amount_Deadfish THEN
		Ext_FeedControl.EXT_Operator.Amount_Fish := 						Ext_FeedControl.EXT_Operator.Amount_Fish - Ext_FeedControl.EXT_Operator.Amount_Deadfish;
	ELSE
		Ext_FeedControl.EXT_Operator.Amount_Fish:=0;
	END_IF;
	
	Ext_FeedControl.EXT_Statistics.Group_Amount_Deadfish := 	Ext_FeedControl.EXT_Statistics.Group_Amount_Deadfish + Ext_FeedControl.EXT_Operator.Amount_Deadfish;
	Ext_FeedControl.EXT_Operator.Amount_Deadfish_Today := 	Ext_FeedControl.EXT_Operator.Amount_Deadfish_Today + Ext_FeedControl.EXT_Operator.Amount_Deadfish;
	Ext_FeedControl.EXT_Operator.Amount_Deadfish:=				0;
	Ext_FeedControl.EXT_Operator.Amount_Deadfish_TS := 		Current_TimeStamp; 
	Ext_FeedControl.EXT_Operator.Add_DeadFish := 					FALSE;
ELSE
	Ext_FeedControl.EXT_Operator.Add_DeadFish := FALSE;
END_IF;

//Timestamp when changing apetite factor
IF Ext_FeedControl.EXT_Operator.Appetite_Factor <> Wrk_AppetiteFactor_Comp THEN
	Ext_FeedControl.EXT_Operator.Appetite_Factor_TS := Current_TimeStamp;
	Wrk_AppetiteFactor_Comp := Ext_FeedControl.EXT_Operator.Appetite_Factor;
END_IF;

//Clear all data when group reset
IF Ext_FeedControl.EXT_Statistics.Group_ResetData THEN
	Ext_FeedControl.EXT_Statistics.Group_ResetData_TS :=DateToString(Current_Date);
	Wrk_ResetGroup:= Current_Date;
	Wrk_GroupTotalFeed:=0;
	Ext_FeedControl.EXT_Operator.Amount_Deadfish:=0;
	Ext_FeedControl.EXT_Operator.Amount_Fish :=0;
	Ext_FeedControl.EXT_Operator.Weight_AVG :=0;
	Ext_FeedControl.EXT_Statistics.Group_TotalFeedAmount:=0;
	Ext_FeedControl.EXT_Statistics.Group_Amount_Deadfish:=0;
	Ext_FeedControl.EXT_Statistics.Group_Days:=0;
	Ext_FeedControl.EXT_Statistics.Group_DegreeDays:=0;
	Ext_FeedControl.EXT_Statistics.Group_SGR_Calculated:=0;
	Ext_FeedControl.EXT_Statistics.Group_TGC_Calculated:=0;
	Ext_FeedControl.EXT_Statistics.Group_EFF_Calculated:=0;
	Ext_FeedControl.EXT_Statistics.Group_BFF_Calculated:=0;
	Ext_FeedControl.EXT_General.Group_Name:='None';
	Ext_FeedControl.EXT_General.Group_Type:='None';	
	Ext_FeedControl.EXT_Statistics.Group_Days:=0;
	Wrk_AVGWeight_Start:=0;
	Wrk_Biomass_Start:=0;
	Ext_FeedControl.EXT_Statistics.Group_ResetData := FALSE;
END_IF;

//Start avg weight register
IF Ext_FeedControl.EXT_Operator.Weight_AVG > 0 AND Wrk_AVGWeight_Start=0 THEN
	Wrk_AVGWeight_Start:=Ext_FeedControl.EXT_Operator.Weight_AVG;
END_IF;

//Start biomass register
IF Ext_FeedControl.EXT_Operator.Biomass_Current > 0 AND Wrk_Biomass_Start=0 THEN
	Wrk_Biomass_Start:=Ext_FeedControl.EXT_Operator.Biomass_Current;
END_IF;

(*************************************************************************
 *	STATE CONTROL
 *************************************************************************)

// FAULT CONTROL
//-------------------
CASE Ext_FeedControl.EXT_Operator.FeedPlan_Select OF
	
	0:
	Wrk_FeedAmountImpossible:= 			(Ext_FeedControl.EXT_Operator.Feed_Amount_Today > 0 AND Ext_FeedControl_Common.INT_Data.FeedPlan1_Intensity>0) AND Ext_FeedControl.EXT_Operator.Pulse_Time < 0.5 OR Ext_FeedControl.EXT_Operator.Pause_Time < 0.5;

	1:
	Wrk_FeedAmountImpossible:= 			(Ext_FeedControl.EXT_Operator.Feed_Amount_Today > 0 AND Ext_FeedControl_Common.INT_Data.FeedPlan2_Intensity>0) AND Ext_FeedControl.EXT_Operator.Pulse_Time < 0.5 OR Ext_FeedControl.EXT_Operator.Pause_Time < 0.5;
	
	2:
	Wrk_FeedAmountImpossible:= 			(Ext_FeedControl.EXT_Operator.Feed_Amount_Today > 0 AND Ext_FeedControl_Common.INT_Data.FeedPlan3_Intensity>0) AND Ext_FeedControl.EXT_Operator.Pulse_Time < 0.5 OR Ext_FeedControl.EXT_Operator.Pause_Time < 0.5;
	
END_CASE;

Wrk_Fault_Interlock:= 								Inp_Interlock;
Wrk_Fault_FCRFactor:=							Ext_FeedControl.EXT_Operator.FCR_Factor_Current=0;
Wrk_Fault_SGRFactor:=							Ext_FeedControl.EXT_Operator.SGR_Factor_Current=0;
Wrk_Fault_FeedScrew1_NotAvailable:=	NOT Inp_FeedScrew1_Available;
Wrk_Fault_FeedScrew1_NotAvailable:=	NOT Inp_FeedScrew2_Available AND Cfg_FeedScrew2_InUse;

//Feedback fault
TON_FeedScrew1_FeedbackConstant(In:=Inp_FeedScrew1_Feedback AND NOT Wrk_OutputFeedScrew1, PT:=TIME#2s);
TON_FeedScrew2_FeedbackConstant(In:=Inp_FeedScrew2_Feedback AND NOT Wrk_OutputFeedScrew2, PT:=TIME#2s);
TON_FeedScrew1_FeedbackMissing(In:=Wrk_OutputFeedScrew1 AND NOT Inp_FeedScrew1_Feedback , PT:=TIME#2s);
TON_FeedScrew2_FeedbackMissing(In:=Wrk_OutputFeedScrew2 AND NOT Inp_FeedScrew2_Feedback , PT:=TIME#2s);

IF TON_FeedScrew1_FeedbackMissing.Q THEN 
	Wrk_FeedSrew1_FeedbackMissing:=TRUE;
ELSIF Ext_FeedControl.EXT_Alarm.AlarmState[6].Acknowledge THEN
	Wrk_FeedSrew1_FeedbackMissing:=FALSE;
END_IF;
IF TON_FeedScrew2_FeedbackMissing.Q THEN 
	Wrk_FeedSrew2_FeedbackMissing:=TRUE;
ELSIF Ext_FeedControl.EXT_Alarm.AlarmState[7].Acknowledge THEN
	Wrk_FeedSrew2_FeedbackMissing:=FALSE;
END_IF;
IF TON_FeedScrew1_FeedbackConstant.Q THEN 
	Wrk_FeedSrew1_FeedbackConstant:=TRUE;
ELSIF Ext_FeedControl.EXT_Alarm.AlarmState[8].Acknowledge THEN
	Wrk_FeedSrew1_FeedbackConstant:=FALSE;
END_IF;
IF TON_FeedScrew2_FeedbackConstant.Q THEN 
	Wrk_FeedSrew2_FeedbackConstant:=TRUE;
ELSIF Ext_FeedControl.EXT_Alarm.AlarmState[9].Acknowledge THEN
	Wrk_FeedSrew2_FeedbackConstant:=FALSE;
END_IF;

//Resetter variabler før løkke
Ext_FeedControl.EXT_General.Sts_Quality := 6; //Good

//STATE 1 - Pulse/pause time fault
HE_StateControl(EXT_StateData:=Ext_FeedControl.EXT_Engineering.StateCfg_1, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_FeedAmountImpossible, 
							Inp_Desc:='Feed amount exceeds capacity', 
							Sts_Quality:=Ext_FeedControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[0].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[0].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[0].Alm_Priority);

//STATE 2 - FCR factor out of bounds
HE_StateControl(EXT_StateData:=Ext_FeedControl.EXT_Engineering.StateCfg_2, 
							Inp_Visibility:=TRUE,
							Inp_State:=Wrk_Fault_FCRFactor, 
							Inp_Desc:='FCR factor out of bounds', 
							Sts_Quality:=Ext_FeedControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[1].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[1].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[1].Alm_Priority);

//STATE 3 - SGR factor out of bounds
HE_StateControl(EXT_StateData:=Ext_FeedControl.EXT_Engineering.StateCfg_3, 
							Inp_Visibility:=Ext_FeedControl.EXT_Operator.Mode=2, //Only in auto mode 
							Inp_State:=Wrk_Fault_SGRFactor,
							Inp_Desc:='SGR factor out of bounds', 
							Sts_Quality:=Ext_FeedControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[2].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[2].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[2].Alm_Priority);


//STATE 4- Interlock
HE_StateControl(EXT_StateData:=Ext_FeedControl.EXT_Engineering.StateCfg_4, 
							Inp_Visibility:=Cfg_InterlockInUse, //Only in auto mode
							Inp_State:=Inp_Interlock, 
							Inp_Desc:='Interlock', 
							Sts_Quality:=Ext_FeedControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[3].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[3].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[3].Alm_Priority);

//STATE 5 - Feed screw 1 not available
HE_StateControl(EXT_StateData:=Ext_FeedControl.EXT_Engineering.StateCfg_5, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_Fault_FeedScrew1_NotAvailable, 
							Inp_Desc:='Screw 1 - Not available', 
							Sts_Quality:=Ext_FeedControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[4].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[4].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[4].Alm_Priority);

//STATE 6 - Feed screw 2 not available
HE_StateControl(EXT_StateData:=Ext_FeedControl.EXT_Engineering.StateCfg_6, 
							Inp_Visibility:=Cfg_FeedScrew2_InUse, //Only when feed screw 2 in use
							Inp_State:=Wrk_Fault_FeedScrew2_NotAvailable, 
							Inp_Desc:='Screw 2 - Not available', 
							Sts_Quality:=Ext_FeedControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[5].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[5].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[5].Alm_Priority);

//STATE 7 - Feed screw 1 missing feedback
HE_StateControl(EXT_StateData:=Ext_FeedControl.EXT_Engineering.StateCfg_7, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_FeedSrew1_FeedbackMissing, 
							Inp_Desc:='Screw 1 - Feedback missing', 
							Sts_Quality:=Ext_FeedControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[6].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[6].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[6].Alm_Priority);

//STATE 8 - Feed screw 2 missing feedback
HE_StateControl(EXT_StateData:=Ext_FeedControl.EXT_Engineering.StateCfg_8, 
							Inp_Visibility:=Cfg_FeedScrew2_InUse, 
							Inp_State:=Wrk_FeedSrew2_FeedbackMissing, 
							Inp_Desc:='Screw 2 - Feedback missing', 
							Sts_Quality:=Ext_FeedControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState,
							Sts_AlarmSuffix=>Wrk_AlarmData[7].Alm_Suffix,
							Sts_AlarmState=>Wrk_AlarmData[7].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[7].Alm_Priority);

//STATE 9 - Feed screw 1 feedback constant
HE_StateControl(EXT_StateData:=Ext_FeedControl.EXT_Engineering.StateCfg_9, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_FeedSrew1_FeedbackConstant, 
							Inp_Desc:='Screw 1 - Feedback constant', 
							Sts_Quality:=Ext_FeedControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[8].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[8].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[8].Alm_Priority);

//STATE 10 - Feed screw 2 feedback constant
HE_StateControl(EXT_StateData:=Ext_FeedControl.EXT_Engineering.StateCfg_10, 
							Inp_Visibility:=Cfg_FeedScrew2_InUse, 
							Inp_State:=Wrk_FeedSrew2_FeedbackConstant, 
							Inp_Desc:='Screw 2 - Feedback constant', 
							Sts_Quality:=Ext_FeedControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState,
							Sts_AlarmSuffix=>Wrk_AlarmData[9].Alm_Suffix,
							Sts_AlarmState=>Wrk_AlarmData[9].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[9].Alm_Priority);
								
(*************************************************************************
 *	ALARM CONTROL
 *************************************************************************)

//Supress if off mode
IF Ext_FeedControl.EXT_Alarm.Sts_SupressIfOff_Visible AND Ext_FeedControl.EXT_Alarm.Cfg_SupressIfOff AND Ext_FeedControl.EXT_Operator.Mode = 0 THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= 'Off mode';
//Supress from FB input
ELSIF Inp_AlmSuppress THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= Inp_AlmSuppressDesc;
ELSE
	FB_AlarmLogic.Inp_AlarmSupress:=FALSE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= '';
END_IF;

(*************************************************************************
 *	EXCECUTING ALARM BLOCK
 *************************************************************************)
 
 FB_AlarmLogic(ENS:=TRUE, 
								 Ext_Alarm:=Ext_FeedControl.EXT_Alarm, 
								 Int_Alarm:=Int_Alarm, 
								 Inp_AlarmData:=Wrk_AlarmData,
								 Inp_LocationData:=Ext_FeedControl.EXT_General.LocationIndex,
								 Inp_Connected_Cabinet:='', 
								 Inp_Connected_Controller:=Cfg_ControllerName, 
								 Inp_Process_TAG:='',
								 Inp_Process_Value:= '',
								 Inp_Process_Desc:=Ext_FeedControl.EXT_General.Process_Desc,
								 Out_AlarmToken=>Wrk_AlarmToken, 
								 Out_AlarmTriggered=>Wrk_AlarmTriggered);

(*************************************************************************
 *	UPDATING STATUS
 *************************************************************************)

IF Ext_FeedControl.EXT_Operator.Mode = 0 THEN
	Ext_FeedControl.EXT_General.StateDesc := 'Feeding set to OFF';
	
ELSIF Ext_FeedControl.EXT_Operator.Mode = 1 THEN
	Ext_FeedControl.EXT_General.StateDesc:= 'Feeding manual amount';

ELSIF Ext_FeedControl.EXT_Operator.Mode = 2 THEN
	IF Ext_FeedControl.EXT_Operator.Feed_Amount_Today=0 THEN
		Ext_FeedControl.EXT_General.StateDesc:= 'Feeding paused - No planned feed today';
	ELSIF (Ext_FeedControl_Common.INT_Data.FeedPlan1_Intensity = 0 AND Ext_FeedControl.EXT_Operator.FeedPlan_Select = 0)
			OR (Ext_FeedControl_Common.INT_Data.FeedPlan2_Intensity = 0 AND Ext_FeedControl.EXT_Operator.FeedPlan_Select = 1)
			OR (Ext_FeedControl_Common.INT_Data.FeedPlan3_Intensity = 0 AND Ext_FeedControl.EXT_Operator.FeedPlan_Select = 2)THEN
		Ext_FeedControl.EXT_General.StateDesc:= 'Feeding paused - No feed this time period';
	ELSIF Ext_FeedControl.EXT_Operator.Biomass_Current = 0 THEN
		Ext_FeedControl.EXT_General.StateDesc:= 'Feeding paused - No biomass to feed';
	ELSIF Ext_FeedControl.EXT_Operator.Temperature_Current < 1 OR  Ext_FeedControl.EXT_Operator.Temperature_Current > 17 THEN
		Ext_FeedControl.EXT_General.StateDesc:= 'Feeding paused - No valid temperature';
	ELSIF Ext_FeedControl.EXT_Operator.SGR_Factor_Current = 0 THEN
		Ext_FeedControl.EXT_General.StateDesc:= 'Feeding paused - No valid feed factor';
	ELSIF Ext_FeedControl.EXT_Operator.Appetite_Factor = 0 THEN
		Ext_FeedControl.EXT_General.StateDesc:= 'Feeding paused - No valid appetitte factor';
	ELSE
		Ext_FeedControl.EXT_General.StateDesc:= 'Feeding ongoing';
	END_IF;
END_IF;

(*************************************************************************
 *	OUTPUT DATA
 *************************************************************************)
 
 Sts_Alarm:=Wrk_AlarmTriggered;
 Out_FeedScrew1_Start:=Wrk_OutputFeedScrew1 OR Wrk_Calibration_StartScrew1;
 Out_FeedScrew2_Start:=Wrk_OutputFeedScrew2 OR Wrk_Calibration_StartScrew2;
